import{_ as e,o as i,c as a,a3 as t}from"./chunks/framework.DH50UWNB.js";const c=JSON.parse('{"title":"Run the images yourself","description":"","frontmatter":{},"headers":[],"relativePath":"run/images.md","filePath":"run/images.md"}'),n={name:"run/images.md"};function h(r,s,o,l,p,d){return i(),a("div",null,[...s[0]||(s[0]=[t(`<h1 id="run-the-images-yourself" tabindex="-1">Run the images yourself <a class="header-anchor" href="#run-the-images-yourself" aria-label="Permalink to &quot;Run the images yourself&quot;">​</a></h1><p>The installer is the simplest way to run Wake. To run it on your own platform instead, such as Kubernetes, an external Postgres or your own proxy, run the two published images.</p><h2 id="the-images" tabindex="-1">The images <a class="header-anchor" href="#the-images" aria-label="Permalink to &quot;The images&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Image</th><th>Runs</th><th>Port</th></tr></thead><tbody><tr><td><code>ghcr.io/dalodev/wake-server:&lt;version&gt;</code></td><td>The API server, MCP at <code>/mcp</code>, OAuth and event streams</td><td><code>3000</code></td></tr><tr><td><code>ghcr.io/dalodev/wake-web:&lt;version&gt;</code></td><td>The web app as static files served by Caddy, forwarding <code>/v1</code> to the server so cookies stay on one origin</td><td><code>5173</code></td></tr></tbody></table><p><code>&lt;version&gt;</code> is the release without the <code>v</code>, such as <code>2.4.0</code>. <code>latest</code> follows the newest release; prereleases such as <code>2.4.0-rc.1</code> never move it. Pin an exact version in production. A release&#39;s <code>compose.yaml</code> names both images by digest too, <code>ghcr.io/dalodev/wake-server:&lt;version&gt;@sha256:...</code>, the digest the release signed: Docker runs that image even if the tag is pushed again.</p><p>Both images run as a user other than root, with a read-only root file system, no capabilities and <code>no-new-privileges</code> (the web image needs a writable <code>/tmp</code>). They hold only what they run.</p><p>Both carry the license they ship under, at <code>/usr/share/licenses/wake/LICENSE</code>, and the label <code>org.opencontainers.image.licenses</code>, set to <code>LicenseRef-Wake-Free-License</code>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line prompt"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --entrypoint</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ghcr.io/dalodev/wake-server:2.4.0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/share/licenses/wake/LICENSE</span></span>
<span class="line prompt"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> image</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> inspect</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --format</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{{index .Config.Labels &quot;org.opencontainers.image.licenses&quot;}}&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ghcr.io/dalodev/wake-server:2.4.0</span></span></code></pre></div><h2 id="layout" tabindex="-1">Layout <a class="header-anchor" href="#layout" aria-label="Permalink to &quot;Layout&quot;">​</a></h2><p>Put both containers behind a TLS reverse proxy that you control:</p><ul><li><code>https://wake.example.com</code> → the web container. Browsers use this origin; the web container forwards <code>/v1</code> to the server.</li><li><code>https://api.wake.example.com</code> → the server container. The CLI, coding agents (MCP and OAuth) and evidence downloads use this origin. It is the server&#39;s <code>PUBLIC_URL</code>.</li><li>Postgres 18, reachable only from the server.</li><li>An S3 bucket (S3, R2 or MinIO) that agents reach for uploads and browsers for downloads, through presigned addresses; see <a href="/wake-dist/docs/run/evidence-storage">Evidence storage</a>.</li></ul><p>For this layout, the server gets:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line prompt"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DATABASE_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">postgres://wake:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">password</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">@db.internal:5432/wake</span></span>
<span class="line prompt"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PUBLIC_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://api.wake.example.com</span></span>
<span class="line prompt"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">WEB_ORIGINS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://wake.example.com</span></span>
<span class="line prompt"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">WEB_APP_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://wake.example.com</span></span>
<span class="line prompt"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TRUST_PROXY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">true</span></span>
<span class="line prompt"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">EVIDENCE_S3_ENDPOINT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">account</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.r2.cloudflarestorage.com</span></span>
<span class="line prompt"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">EVIDENCE_S3_BUCKET</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">wake-evidence</span></span>
<span class="line prompt"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">EVIDENCE_S3_ACCESS_KEY_ID</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">key</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line prompt"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">EVIDENCE_S3_SECRET_ACCESS_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">secret</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line prompt"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">EVIDENCE_S3_REGION</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">auto</span></span></code></pre></div><p>Every variable, and the web container&#39;s two, are in <a href="/wake-dist/docs/reference/environment">Server environment</a>. Keep secrets in your platform&#39;s secret store, never in an image or a committed file.</p><h2 id="run-the-containers" tabindex="-1">Run the containers <a class="header-anchor" href="#run-the-containers" aria-label="Permalink to &quot;Run the containers&quot;">​</a></h2><p>This example runs both containers on one host with Docker; any container platform works the same way:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line prompt"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> network</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wake</span></span>
<span class="line prompt"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">hardened</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;--read-only --cap-drop ALL --security-opt no-new-privileges&quot;</span></span>
<span class="line prompt"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wake-server</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --network</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wake</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $hardened </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">--env-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/wake/server.env</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 127.0.0.1:3000:3000</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ghcr.io/dalodev/wake-server:2.4.0</span></span>
<span class="line prompt"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wake-web</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --network</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wake</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $hardened </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">--tmpfs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> WAKE_API_PROXY=http://wake-server:3000</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> WAKE_S3_URL=https://</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">accoun</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.r2.cloudflarestorage.com</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 127.0.0.1:5173:5173</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ghcr.io/dalodev/wake-web:2.4.0</span></span>
<span class="line prompt"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:3000/health</span></span></code></pre></div><p><code>$hardened</code> is unquoted on purpose, so the shell splits it into its options. Your TLS proxy should add <code>Strict-Transport-Security</code> to both origins.</p><p>Every server response carries <code>X-Content-Type-Options: nosniff</code>, <code>Referrer-Policy: no-referrer</code>, <code>X-Frame-Options: DENY</code> and a <code>Content-Security-Policy</code>. The web container&#39;s policy allows images from the origin of its <code>WAKE_S3_URL</code>, so evidence images load from the storage. The web container answers any <code>Host</code>; your proxy decides which names reach it.</p><h2 id="migrations" tabindex="-1">Migrations <a class="header-anchor" href="#migrations" aria-label="Permalink to &quot;Migrations&quot;">​</a></h2><p>The server applies pending database migrations when it starts (<code>MIGRATE_ON_START=true</code>). A Postgres advisory lock serializes them, so several replicas can start at once; only one migrates. Migrations only add to the schema. To migrate as a separate step, run one server with <code>MIGRATE_ON_START=true</code> first and the others with <code>false</code>.</p><h2 id="upgrade-order" tabindex="-1">Upgrade order <a class="header-anchor" href="#upgrade-order" aria-label="Permalink to &quot;Upgrade order&quot;">​</a></h2><ol><li>Back up Postgres.</li><li>Deploy the new server image (it migrates on start) and the new web image together: a newer server can send kinds of activity an older web app cannot read.</li><li>Ask everyone to update their <code>wake</code> CLI. A newer CLI may send fields an older server refuses, while a newer server accepts every older CLI.</li></ol><p>On an installation, <code>wake-server upgrade</code> does steps 1 and 2. <code>wake upgrade</code> on the machine that runs the installation does them too, then upgrades that machine&#39;s CLI; CLIs installed globally on other machines follow by themselves at their next agent session. See <a href="/wake-dist/docs/run/upgrade#which-command-to-run">Which command to run</a>.</p><h2 id="move-onto-an-installation" tabindex="-1">Move onto an installation <a class="header-anchor" href="#move-onto-an-installation" aria-label="Permalink to &quot;Move onto an installation&quot;">​</a></h2><p>The installer does not adopt a deployment you run yourself. To move one onto it, copy the database into a new installation:</p><ol><li><p>Upgrade the existing deployment to the release you will install, or note its version: the installation must run the same release or a newer one.</p></li><li><p>Stop the existing server, so nothing writes during the copy, and dump its database without owners, since the installation&#39;s database user is <code>wake</code>. Use a <code>pg_dump</code> of the same major version as the Postgres it reads, or newer:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line prompt"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pg_dump</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$DATABASE_URL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-owner</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-privileges</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Z</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 6</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wake-move.sql.gz</span></span></code></pre></div></li><li><p><a href="/wake-dist/docs/start/install">Install Wake</a> on the new machine or directory, and do not create an account in it yet.</p></li><li><p>Copy <code>wake-move.sql.gz</code> into the installation&#39;s <code>backups/</code>, named with the version the deployment runs and a UTC time, such as <code>wake-2.4.0-20261024T101500Z.sql.gz</code>, and restore it with <code>wake-server restore</code> (see <a href="/wake-dist/docs/run/backup">Back up and restore</a>).</p></li><li><p>Copy the evidence files: the objects of your old bucket go into the installation&#39;s <code>wake-evidence</code> bucket in MinIO (an S3 client such as MinIO&#39;s <code>mc mirror</code> does it). Evidence whose file is missing cannot be opened; everything else works without it.</p></li><li><p>Point the clients at the new address. The installation serves the app and the API on one origin, where your layout may have used two. In each connected repository, set <code>server</code> in <code>.wake/config.json</code> to the new address, run <code>wake login --server</code> with it and <code>wake connect &lt;agent&gt;</code> (it rewrites the MCP address), commit, and sign the agent in again.</p></li></ol><p>The installation starts with no sign-in provider and no external storage, so accounts that only sign in with a provider cannot sign in until you turn that provider on (<a href="/wake-dist/docs/run/sign-in-providers">Sign-in providers</a>).</p>`,28)])])}const g=e(n,[["render",h]]);export{c as __pageData,g as default};
